K40_PS.avc_code:
// IF-Constraints based on provided mappings

// Constraint for PS03
pc.K40_PS = 'PS03' IF specified dummy AND (pc.K40_rod < '200' AND pc.K40_fg_af < '3' AND (pc.K40_schp = '04' OR pc.K40_schp = '06') AND pc.K40_ko <> '09').

// Constraint for PW04
pc.K40_PS = 'PW04' IF (pc.K40_rod < '200' AND pc.K40_fg_af < '3' AND (pc.K40_schp = '04' OR pc.K40_schp = '06') AND pc.K40_ko <> '09') AND (pc.K40_fg_af < '0') AND (pc.K40_abl = '0').

// Constraints for PS12 and PS13 (same condition)
pc.K40_PS IN ('PS12', 'PS13') IF (pc.K40_abl = '0') AND pc.K40_ko <> '09'.

// Constraint for PS06
pc.K40_PS = 'PS06' IF pc.K40_ko <> '09'.

// Constraint for PW08
pc.K40_PS = 'PW08' IF pc.K40_abl = '0'.
